import { useMemo, useRef } from "react";
import { RotateCcw, ZoomIn, ZoomOut } from "lucide-react";
import { Workspace } from "../components/layout/Shell.jsx";
import {
  Help,
  help,
  NumberControl,
  SelectControl,
  Toggle,
  Panel,
  Metrics,
  Notice,
} from "../components/ui/Controls.jsx";
import { ExportBar } from "../components/ui/ExportBar.jsx";
import { useToast } from "../components/ui/Toast.jsx";
import { PresetManager } from "../components/presets/PresetManager.jsx";
import { ExplorationGuide } from "../components/learning/ExplorationGuide.jsx";
import { CanvasImage } from "../components/visual/CanvasImage.jsx";
import { LineChart } from "../components/visual/LineChart.jsx";
import { useStudioStore } from "../store/useStudioStore.js";
import { useElementSize } from "../hooks/useBrowser.js";
import { useSimulation } from "../hooks/useSimulation.js";
import * as physics from "../services/wave/physics.js";
import { waveRaster } from "../services/wave-export.js";
import {
  parameterHelp as H,
  explorationGuide,
} from "../utils/wave-learning.js";
import {
  downloadCanvas,
  downloadBlob,
  makeReport,
  reportSVG,
  format,
  waveNames,
} from "../utils/export.js";
const modes = Object.entries(waveNames);
const presets = [
  ["young", "Young classico"],
  ["red", "Luce rossa · 650 nm"],
  ["green", "Luce verde · 532 nm"],
  ["blue", "Luce blu · 450 nm"],
  ["dual", "Rosso + blu"],
  ["airy", "Foro circolare · Airy"],
  ["slit", "Fenditura singola"],
];
export default function WavePage() {
  const p = useStudioStore((s) => s.wave),
    update = useStudioStore((s) => s.updateWave),
    setState = useStudioStore((s) => s.setState),
    theme = useStudioStore((s) => s.theme),
    toast = useToast();
  const [viewRef, size] = useElementSize(),
    main = useRef(null),
    first = useRef(null),
    second = useRef(null),
    chart = useRef(null),
    drag = useRef(null);
  const aspect = size.height / size.width;
  const params = useMemo(
    () => ({
      ...p,
      span: p.autoScale ? physics.automaticSpan(p, aspect) : p.span,
      cx: p.autoScale ? 0 : p.cx,
      cy: p.autoScale ? 0 : p.cy,
    }),
    [p, aspect],
  );
  const width = p.quality,
    height = Math.max(100, Math.round(width * aspect));
  const validity = useMemo(() => {
    const check = physics.validity(params),
      edge =
        (Math.hypot(
          Math.abs(params.cx) + params.span / 2,
          Math.abs(params.cy) + (params.span * aspect) / 2,
        ) *
          1e-3) /
        params.screen;
    const scale =
      (Math.min(params.lambda1, params.dual ? params.lambda2 : params.lambda1) *
        1e-9 *
        params.screen) /
      (physics.isDouble(params)
        ? physics.separation(params)
        : physics.aperture(params));
    if (edge > 0.1)
      return {
        ...check,
        valid: false,
        reason:
          "Le direzioni ai bordi superano il campo paraassiale (|r|/L > 0,1). Riduci il campo o ricentra la vista.",
      };
    if ((params.span * 1e-3) / width > scale / 6)
      return {
        ...check,
        valid: false,
        reason:
          "Frange sottocampionate. Aumenta la risoluzione o riduci il campo visualizzato.",
      };
    return check;
  }, [params, aspect, width]);
  const context = useMemo(
    () => ({ wave: true, width, height }),
    [width, height],
  );
  const { result, busy, error, backend } = useSimulation(
    "wave",
    params,
    context,
    { enabled: validity.valid },
  );
  const ready = !!result && !busy && !error && validity.valid;
  const current = result?.params || params;
  const profile = useMemo(() => physics.profile(current), [current]);
  const series = useMemo(
    () =>
      [
        ["Combinata", profile.sum, "#79dfc7"],
        ["λ₁", profile.a, "#f8ad8b"],
        ...(current.dual ? [["λ₂", profile.b, "#7eaaff"]] : []),
      ].map(([label, values, color]) => ({
        label,
        borderColor: color,
        color,
        data: Array.from(profile.x, (x, i) => ({ x: x * 1000, y: values[i] })),
      })),
    [profile, current.dual],
  );
  const num = (key, label, min, max, step, unit) => (
    <NumberControl
      key={key}
      label={label}
      value={p[key]}
      onChange={(value) => update({ [key]: value })}
      min={min}
      max={max}
      step={step}
      unit={unit}
      entry={H[key]}
    />
  );
  function preset(key) {
    const n = physics.defaults();
    if (key === "green") n.lambda1 = 532;
    if (key === "blue") n.lambda1 = 450;
    if (key === "dual") n.dual = true;
    if (key === "airy") n.mode = "single-hole";
    if (key === "slit") n.mode = "single-slit";
    setState("wave", n);
  }
  const controls = (
    <>
      <section className="sidebar-section">
        <div className="section-heading">
          <h3>Configurazione</h3>
          <button
            className="icon-button"
            aria-label="Ripristina ottica ondulatoria"
            onClick={() => setState("wave", physics.defaults())}
          >
            <RotateCcw size={16} />
          </button>
        </div>
        <SelectControl
          label="Preset di laboratorio"
          value=""
          onChange={preset}
          options={[["", "Scegli un esperimento…"], ...presets]}
          entry={H.preset}
        />
        <SelectControl
          label="Fenomeno"
          value={p.mode}
          onChange={(mode) => update({ mode })}
          options={modes}
          entry={help(
            "Configurazione delle aperture",
            "Scegli una o due aperture, rettangolari o circolari.",
            "Con due aperture compaiono frange d’interferenza dentro l’inviluppo di diffrazione. Con una osservi solo l’inviluppo.",
            "Confronta il profilo centrale e la simmetria della figura.",
          )}
        />
      </section>
      <section className="sidebar-section">
        <h3>Sorgenti luminose</h3>
        <Toggle
          label="Due lunghezze d’onda"
          checked={p.dual}
          onChange={(dual) => update({ dual })}
          entry={H.dual}
        />
        <Toggle
          label="Canale λ₁ attivo"
          checked={p.on1}
          onChange={(on1) => update({ on1 })}
          entry={H.on1}
        />
        {num("lambda1", "Lunghezza d’onda λ₁", 380, 780, 1, "nm")}
        {num("power1", "Intensità I₁", 0, 2, 0.01, "rel.")}
        {p.dual && (
          <>
            <Toggle
              label="Canale λ₂ attivo"
              checked={p.on2}
              onChange={(on2) => update({ on2 })}
              entry={H.on2}
            />
            {num("lambda2", "Lunghezza d’onda λ₂", 380, 780, 1, "nm")}
            {num("power2", "Intensità I₂", 0, 2, 0.01, "rel.")}
          </>
        )}
      </section>
      <section className="sidebar-section">
        <h3>Geometria dell’apparato</h3>
        {physics.isCircular(p)
          ? num("diameter", "Diametro D", 10, 1000, 1, "µm")
          : num("width", "Larghezza a", 5, 500, 1, "µm")}
        {physics.isDouble(p) &&
          (physics.isCircular(p)
            ? num("separationHole", "Separazione dei fori d", 20, 3000, 1, "µm")
            : num(
                "separationSlit",
                "Separazione fenditure d",
                10,
                2000,
                1,
                "µm",
              ))}
        {num("source", "Sorgente → apertura S", 0.1, 100, 0.1, "m")}
        {num("screen", "Apertura → schermo L", 0.1, 20, 0.01, "m")}
      </section>
      <section className="sidebar-section">
        <h3>Visualizzazione</h3>
        <SelectControl
          label="Colori"
          value={p.palette}
          onChange={(palette) => update({ palette })}
          options={[
            ["spectral", "Tonalità spettrali"],
            ["false", "Falsi colori"],
          ]}
          entry={H.palette}
        />
        {num("exposure", "Esposizione", 0.1, 10, 0.1, "×")}
        <Toggle
          label="Scala automatica"
          checked={p.autoScale}
          onChange={(autoScale) => update({ autoScale })}
          entry={H.autoScale}
        />
        {!p.autoScale && (
          <>
            <NumberControl
              label="Campo orizzontale"
              value={p.span}
              min={0.02}
              max={2000}
              step={0.02}
              unit="mm"
              entry={H.span}
              onChange={(span) => update({ span })}
            />
            {num("cx", "Centro x", -100, 100, 0.01, "mm")}
            {num("cy", "Centro y", -100, 100, 0.01, "mm")}
          </>
        )}
        <Toggle
          label="Riferimenti teorici"
          checked={p.markers}
          onChange={(markers) => update({ markers })}
          entry={H.markers}
        />
        <SelectControl
          label="Risoluzione del raster"
          value={p.quality}
          onChange={(quality) => update({ quality: Number(quality) })}
          options={[
            [600, "600 px · rapida"],
            [900, "900 px · bilanciata"],
            [1600, "1600 px · alta"],
          ]}
          entry={H.quality}
        />
      </section>
      <PresetManager engine="wave" />
    </>
  );
  const zoom = (factor) =>
    update({
      autoScale: false,
      span: Math.max(0.02, Math.min(2000, params.span * factor)),
      cx: params.cx,
      cy: params.cy,
    });
  const panelList = () => [
    { title: "Figura sullo schermo", canvas: main.current },
    { title: "Profilo centrale y = 0", canvas: chart.current },
    ...(current.dual
      ? [
          { title: "Componente λ₁", canvas: first.current },
          { title: "Componente λ₂", canvas: second.current },
        ]
      : []),
  ];
  function report() {
    return makeReport({
      title: "Simulatore Ottica Ondulatoria",
      params: current,
      metrics: [
        waveNames[current.mode],
        `λ₁ ${current.lambda1} nm`,
        `L ${current.screen} m`,
      ],
      panels: panelList(),
    });
  }
  const exportCSV = () => {
    const lines = [
      "# Ottica Studio; lunghezze in metri; intensita relative",
      `# ${JSON.stringify(current)}`,
      "x_m,I1,I2,I_totale",
    ];
    for (let i = 0; i < profile.x.length; i++)
      lines.push(
        [profile.x[i], profile.a[i], profile.b[i], profile.sum[i]].join(","),
      );
    downloadBlob(
      new Blob([lines.join("\n")], { type: "text/csv;charset=utf-8" }),
      "ottica-profilo.csv",
    );
  };
  return (
    <Workspace controls={controls}>
      <div className="page-heading">
        <div>
          <span className="eyebrow">
            Laboratorio 01 · Interferenza e diffrazione
          </span>
          <h1>Simulatore Ottica Ondulatoria</h1>
          <p>
            Dalle aperture alla figura sullo schermo. Esplora, misura,
            confronta.
          </p>
        </div>
        <ExportBar
          disabled={!ready}
          onPNG={() => downloadCanvas(main.current, "ottica-figura.png")}
          onCSV={exportCSV}
          onSVG={() =>
            downloadBlob(
              reportSVG({
                title: "Ottica ondulatoria",
                params: current,
                panels: panelList(),
                series,
                xMax: current.cx + current.span / 2,
                xLabel: "x (mm)",
              }),
              "ottica-report.svg",
            )
          }
          onScreenshot={() => downloadCanvas(report(), "ottica-report.png")}
        />
      </div>
      <Metrics
        items={[
          {
            label: physics.isDouble(p) ? "Primo ordine λ₁" : "Primo minimo λ₁",
            value: format(
              physics.firstFeature(current, current.lambda1) * 1000,
            ),
            unit: "mm",
            entry: H.feature,
          },
          {
            label: "Minimo dell’inviluppo",
            value: format(
              physics.firstMinimum(current, current.lambda1) * 1000,
            ),
            unit: "mm",
            entry: H.envelope,
          },
          {
            label: "Scostamento λ₁ / λ₂",
            value: p.dual
              ? format(
                  Math.abs(
                    physics.firstFeature(current, current.lambda1) -
                      physics.firstFeature(current, current.lambda2),
                  ) * 1000,
                )
              : "—",
            unit: "mm",
            entry: H.fringeShift,
          },
          {
            label: "Indice di campo F",
            value: format(validity.F, 4),
            entry: H.fresnel,
          },
        ]}
      />
      {!validity.valid && (
        <Notice tone="error">
          {validity.reason} La figura precedente non è un risultato valido per i
          parametri correnti.
        </Notice>
      )}
      {error && <Notice tone="error">{error}</Notice>}
      <Panel
        title={waveNames[p.mode]}
        kicker="01 · Figura bidimensionale"
        actions={
          <>
            <span className="status-dot" />
            <span className="muted text-xs">
              {busy && validity.valid
                ? "Calcolo…"
                : ready
                  ? `${format(result.ms, 1)} ms · ${backend}`
                  : "Verifica i parametri"}
            </span>
            <button
              className="icon-button"
              aria-label="Ingrandisci figura"
              onClick={() => zoom(0.8)}
            >
              <ZoomIn size={16} />
            </button>
            <button
              className="icon-button"
              aria-label="Riduci figura"
              onClick={() => zoom(1.25)}
            >
              <ZoomOut size={16} />
            </button>
            <button
              className="icon-button"
              aria-label="Ricentra figura"
              onClick={() => update({ autoScale: true, cx: 0, cy: 0 })}
            >
              <RotateCcw size={16} />
            </button>
          </>
        }
      >
        <div
          ref={viewRef}
          className={`wave-stage ${!validity.valid || error ? "invalid-stage" : ""}`}
        >
          <CanvasImage
            ref={main}
            source={result}
            label="Figura di interferenza o diffrazione sullo schermo"
            onWheel={(e) => {
              zoom(e.deltaY > 0 ? 1.1 : 1 / 1.1);
            }}
            onPointerDown={(e) => {
              e.currentTarget.setPointerCapture(e.pointerId);
              drag.current = {
                x: e.clientX,
                y: e.clientY,
                cx: params.cx,
                cy: params.cy,
                span: params.span,
              };
            }}
            onPointerMove={(e) => {
              if (!drag.current) return;
              const rect = e.currentTarget.getBoundingClientRect(),
                d = drag.current;
              update({
                autoScale: false,
                span: d.span,
                cx: d.cx - ((e.clientX - d.x) / rect.width) * d.span,
                cy: d.cy + ((e.clientY - d.y) / rect.width) * d.span,
              });
            }}
            onPointerUp={() => {
              drag.current = null;
            }}
          />
          {p.markers &&
            result &&
            [current.lambda1, ...(current.dual ? [current.lambda2] : [])].map(
              (lambda, i) =>
                [-1, 1].map((sign) => {
                  const x = sign * physics.firstFeature(current, lambda) * 1000,
                    percent = 50 + ((x - current.cx) / current.span) * 100;
                  return percent >= 0 && percent <= 100 ? (
                    <div
                      key={`${i}-${sign}`}
                      className={`fringe-marker channel-${i}`}
                      style={{ left: `${percent}%` }}
                    >
                      <span>λ{i + 1}</span>
                    </div>
                  ) : null;
                }),
            )}
          <span className="stage-caption">
            y ↑ · x → · {format(current.cx - current.span / 2)} …{" "}
            {format(current.cx + current.span / 2)} mm
          </span>
        </div>
        <div className="panel-foot">
          <span>
            Glissa per spostare · rotella o pulsanti per lo zoom · profilo
            calcolato a y = 0
          </span>
          <button
            className="text-button"
            disabled={!ready}
            onClick={async () => {
              try {
                toast("Generazione PNG 4K…");
                await downloadCanvas(
                  await waveRaster(current, 3840, 2160, aspect),
                  "ottica-4k.png",
                );
                toast("PNG 4K esportato.");
              } catch (e) {
                toast(e.message);
              }
            }}
          >
            Esporta PNG 4K
          </button>
        </div>
      </Panel>
      {p.dual && (
        <div className="two-grid">
          <Panel
            title={`λ₁ · ${current.lambda1} nm`}
            kicker="Componente separata"
          >
            <CanvasImage
              ref={first}
              source={
                result?.buffers[1] && {
                  width: result.width,
                  height: result.height,
                  buffers: [result.buffers[1]],
                }
              }
              label="Prima lunghezza d’onda"
            />
          </Panel>
          <Panel
            title={`λ₂ · ${current.lambda2} nm`}
            kicker="Componente separata"
          >
            <CanvasImage
              ref={second}
              source={
                result?.buffers[2] && {
                  width: result.width,
                  height: result.height,
                  buffers: [result.buffers[2]],
                }
              }
              label="Seconda lunghezza d’onda"
            />
          </Panel>
        </div>
      )}
      <Panel
        title="Profilo di intensità"
        kicker="02 · Sezione centrale dello schermo"
      >
        <LineChart
          ref={chart}
          series={series}
          xLabel="Posizione x sullo schermo (mm)"
          yLabel="Intensità relativa"
          theme={theme}
        />
        <p className="panel-note">
          Le intensità dei due canali si sommano senza termine di fase
          incrociato. I riferimenti indicano gli ordini ideali; l’inviluppo può
          spostare i massimi locali.
        </p>
      </Panel>
      <ExplorationGuide guide={explorationGuide} />
    </Workspace>
  );
}
