/** Dedicated worker for 4K exports. Letterboxing preserves the validated physical
 * field and its aspect ratio instead of rendering a larger, unvalidated y range. */
export function waveRaster(
  p,
  width = 3840,
  height = 2160,
  aspect = height / width,
) {
  return new Promise((resolve, reject) => {
    const worker = new Worker(
      new URL("./wave/renderer.worker.js", import.meta.url),
      { type: "module" },
    );
    const rasterWidth = Math.max(
        1,
        Math.min(width, Math.round(height / aspect)),
      ),
      rasterHeight = Math.max(1, Math.round(rasterWidth * aspect));
    worker.onmessage = ({ data }) => {
      worker.terminate();
      const raster = document.createElement("canvas");
      raster.width = data.width;
      raster.height = data.height;
      raster
        .getContext("2d")
        .putImageData(
          new ImageData(
            new Uint8ClampedArray(data.buffers[0]),
            data.width,
            data.height,
          ),
          0,
          0,
        );
      const canvas = document.createElement("canvas");
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext("2d");
      ctx.fillStyle = "#03070c";
      ctx.fillRect(0, 0, width, height);
      ctx.drawImage(
        raster,
        Math.round((width - raster.width) / 2),
        Math.round((height - raster.height) / 2),
      );
      resolve(canvas);
    };
    worker.onerror = (event) => {
      worker.terminate();
      reject(Error(event.message));
    };
    worker.postMessage({
      id: 1,
      p,
      width: rasterWidth,
      height: rasterHeight,
      components: false,
    });
  });
}
